INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('8210e0ee-f553-5cb0-a771-2183105cd661','FA01','Người bất tỉnh hoặc không đáp ứng','CIRCULATION','Dùng bài tiếp cận, không suy nguyên nhân mất ý thức. Không kích thích đau cho người không chuyên.','["Người bất tỉnh hoặc không đáp ứng"]'::jsonb,'Dùng bài tiếp cận, không suy nguyên nhân mất ý thức. Không kích thích đau cho người không chuyên.','Dùng chung kiểm tra đáp ứng, gọi hỗ trợ và theo dõi thở; khi cần CPR phải dùng bài đúng độ tuổi.','{"PNT2024":{"status":"PARTIAL","pages":[10,13]},"NHI2022":{"status":"DIRECT","pages":[19,22]}}'::jsonb,1,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('0b14f81f-ea45-5c18-9b9e-763bebedbd41','FA02','Ngừng tim và CPR/AED','CIRCULATION','Loại bắt mạch cho người không chuyên. RCUK 2025 làm nguồn đối chiếu cho vị trí ép, gọi sớm và AED.','["Ngừng tim và CPR/AED"]'::jsonb,'Loại bắt mạch cho người không chuyên. RCUK 2025 làm nguồn đối chiếu cho vị trí ép, gọi sớm và AED.','Tách người lớn/trẻ em: độ sâu ép, cách đặt tay, thổi ban đầu và tỉ lệ ép/thổi khác nhau.','{"PNT2024":{"status":"DIRECT","pages":[42,45]},"NHI2022":{"status":"DIRECT","pages":[19,26]}}'::jsonb,2,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('a244809f-f145-5432-a8f2-f038469f35b5','FA03','Hóc dị vật','CIRCULATION','Đọc hình PDF để tránh đảo thứ tự text. Trẻ chỉ biên soạn biến thể trên 5 tuổi. Không dùng chung thủ thuật trẻ nhỏ.','["Hóc dị vật"]'::jsonb,'Đọc hình PDF để tránh đảo thứ tự text. Trẻ chỉ biên soạn biến thể trên 5 tuổi. Không dùng chung thủ thuật trẻ nhỏ.','Tách người lớn/trẻ em: tư thế và lực thao tác theo kích thước; bài trẻ em giới hạn trên 5 tuổi theo nguồn đã chọn.','{"PNT2024":{"status":"DIRECT","pages":[14,15]},"NHI2022":{"status":"DIRECT","pages":[59,63]}}'::jsonb,3,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('a441bbef-e3f3-5a6b-ba8a-2afbd9583954','FA04','Đuối nước','CIRCULATION','Phần người lớn trong PNT rất ngắn; chọn bài trẻ em có hướng dẫn đầy đủ hơn. Không tự xuống nước cứu.','["Đuối nước"]'::jsonb,'Phần người lớn trong PNT rất ngắn; chọn bài trẻ em có hướng dẫn đầy đủ hơn. Không tự xuống nước cứu.','Tách người lớn/trẻ em vì hồi sức sau đuối nước dùng kỹ thuật CPR theo độ tuổi.','{"PNT2024":{"status":"PARTIAL","pages":[34,34]},"NHI2022":{"status":"DIRECT","pages":[103,108]}}'::jsonb,4,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('07b49d3d-1ae7-5a34-961d-96d9aa0708bf','FA05','Chảy máu ngoài','TRAUMA','Giữ riêng người lớn/trẻ em; không trì hoãn gọi khi chảy máu nặng.','["Chảy máu ngoài"]'::jsonb,'Giữ riêng người lớn/trẻ em; không trì hoãn gọi khi chảy máu nặng.','Dùng chung ép trực tiếp và bảo vệ vết thương; giữ lưu ý giám sát và gọi hỗ trợ sớm cho trẻ.','{"PNT2024":{"status":"DIRECT","pages":[16,17]},"NHI2022":{"status":"DIRECT","pages":[39,48]}}'::jsonb,5,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('9e1d205d-5a38-580d-8c04-0ce189f9467e','FA06','Vết thương nhỏ và trầy xước','TRAUMA','PNT chỉ nói cầm máu, không đủ bài vệ sinh vết trầy. Chọn NHI 50–51; không tự chỉ định kháng sinh.','["Vết thương nhỏ và trầy xước"]'::jsonb,'PNT chỉ nói cầm máu, không đủ bài vệ sinh vết trầy. Chọn NHI 50–51; không tự chỉ định kháng sinh.','Dùng chung rửa sạch và che vết nông; trẻ cần người lớn hỗ trợ.','{"PNT2024":{"status":"PARTIAL","pages":[16,16]},"NHI2022":{"status":"DIRECT","pages":[50,51]}}'::jsonb,6,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('dab1b20c-fba7-5c3f-82f4-83ae17f9d626','FA07','Chảy máu cam','TRAUMA','NHI trang 52 ghi ngửa đầu, khác PNT 16 và NHS. Không đưa tư thế ngửa đầu vào bài; dùng cúi về trước.','["Chảy máu cam"]'::jsonb,'NHI trang 52 ghi ngửa đầu, khác PNT 16 và NHS. Không đưa tư thế ngửa đầu vào bài; dùng cúi về trước.','Dùng chung cúi trước và bóp phần mềm mũi; giữ chỉ định khám riêng cho trẻ dưới 2 tuổi.','{"PNT2024":{"status":"DIRECT","pages":[16,16]},"NHI2022":{"status":"CONFLICT","pages":[52,53]}}'::jsonb,7,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('bae89c4a-8406-53b7-8c54-aa3f458a2bb1','FA08','Nghi gãy xương','TRAUMA','Không biến dấu khám lạo xạo/cử động bất thường thành hành động kiểm tra của người dùng.','["Nghi gãy xương"]'::jsonb,'Không biến dấu khám lạo xạo/cử động bất thường thành hành động kiểm tra của người dùng.','Dùng chung giữ yên, đỡ chi, không nắn và chuyển đánh giá y tế.','{"PNT2024":{"status":"DIRECT","pages":[18,19]},"NHI2022":{"status":"DIRECT","pages":[30,35]}}'::jsonb,8,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('43f5cc49-79ed-592f-9aac-ca7eb267b537','FA09','Bong gân và trật khớp','TRAUMA','Tách bong gân và trật khớp. NHI chỉ nhắc trong phần ngã, không đủ thay cho hai bài riêng.','["Bong gân và trật khớp"]'::jsonb,'Tách bong gân và trật khớp. NHI chỉ nhắc trong phần ngã, không đủ thay cho hai bài riêng.','Dùng chung chăm sóc ban đầu theo loại chấn thương; tách bong gân/trật khớp, không tách theo tuổi.','{"PNT2024":{"status":"DIRECT","pages":[20,23]},"NHI2022":{"status":"PARTIAL","pages":[69,70]}}'::jsonb,9,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('259a716e-249c-5f43-8ed1-3b7ef2953268','FA10','Chấn thương đầu, cổ hoặc cột sống','TRAUMA','Nội dung rải trong nguyên tắc/tai nạn; chọn hạn chế di chuyển, ưu tiên đường thở. Không chỉ dẫn tự buộc/nẹp cổ.','["Chấn thương đầu, cổ hoặc cột sống"]'::jsonb,'Nội dung rải trong nguyên tắc/tai nạn; chọn hạn chế di chuyển, ưu tiên đường thở. Không chỉ dẫn tự buộc/nẹp cổ.','Dùng chung hạn chế di chuyển và ưu tiên đường thở; không hướng dẫn kỹ thuật nẹp cổ.','{"PNT2024":{"status":"PARTIAL","pages":[10,12]},"NHI2022":{"status":"PARTIAL","pages":[13,14,68,70]}}'::jsonb,10,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('7cf89dce-4b3e-5060-8173-af30dcbf1fa1','FA11','Bỏng','ENVIRONMENT','Giới hạn theo tác nhân. Loại uống bù dịch và băng phức tạp; không dùng bài nhiệt thay cho hóa chất/điện.','["Bỏng"]'::jsonb,'Giới hạn theo tác nhân. Loại uống bù dịch và băng phức tạp; không dùng bài nhiệt thay cho hóa chất/điện.','Dùng chung làm mát bỏng nhiệt nhỏ, da chưa tróc; giữ lưu ý đánh giá y tế cho trẻ và tránh hạ thân nhiệt.','{"PNT2024":{"status":"DIRECT","pages":[35,37]},"NHI2022":{"status":"DIRECT","pages":[86,88]}}'::jsonb,11,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('9e48989b-4824-5b64-bee6-afcc95de49a4','FA12','Điện giật','ENVIRONMENT','Nguồn điện lớn cần điện lực. Không chuyển câu lượng giá NHI 89 thành chỉ dẫn kéo dây bằng tay.','["Điện giật"]'::jsonb,'Nguồn điện lớn cần điện lực. Không chuyển câu lượng giá NHI 89 thành chỉ dẫn kéo dây bằng tay.','Dùng chung an toàn điện và theo dõi; CPR phải phù hợp độ tuổi.','{"PNT2024":{"status":"DIRECT","pages":[38,41]},"NHI2022":{"status":"DIRECT","pages":[85,86]}}'::jsonb,12,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('e972a118-8bdf-5238-8676-40112f2dc43e','FA13','Say nóng và sốc nhiệt','ENVIRONMENT','Không tìm thấy hướng dẫn hoặc mục chủ đề trong hai PDF đã đọc. Nguồn chính cho bài là NHS.','["Say nóng và sốc nhiệt"]'::jsonb,'Không tìm thấy hướng dẫn hoặc mục chủ đề trong hai PDF đã đọc. Nguồn chính cho bài là NHS.','NHS mô tả triệu chứng và làm mát chung cho người lớn/trẻ em.','{"PNT2024":{"status":"NOT_FOUND","pages":[]},"NHI2022":{"status":"NOT_FOUND","pages":[]}}'::jsonb,13,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('86719c2e-923a-558f-bbbd-309e81b86c63','FA14','Dấu hiệu nghi đột quỵ','OTHER','PNT có BE FAST dạng ảnh. Không tìm thấy mục đột quỵ trong NHI. Chỉ biên soạn bài người lớn.','["Dấu hiệu nghi đột quỵ"]'::jsonb,'PNT có BE FAST dạng ảnh. Không tìm thấy mục đột quỵ trong NHI. Chỉ biên soạn bài người lớn.','Dùng chung nhận biết triệu chứng thần kinh đột ngột và gọi cấp cứu; NHS xác nhận có thể xảy ra ở mọi tuổi.','{"PNT2024":{"status":"DIRECT","pages":[31,33]},"NHI2022":{"status":"NOT_FOUND","pages":[]}}'::jsonb,14,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('264d76d4-90db-57f7-b8ad-f18364caf371','FA15','Co giật','OTHER','Có từ co giật trong nguyên tắc/ngộ độc và lượng giá; không có bài sơ cứu cơn độc lập. Dùng NHS.','["Co giật"]'::jsonb,'Có từ co giật trong nguyên tắc/ngộ độc và lượng giá; không có bài sơ cứu cơn độc lập. Dùng NHS.','Dùng chung bảo vệ trong cơn và theo dõi sau cơn; không hướng dẫn thuốc hay điều trị nguyên nhân.','{"PNT2024":{"status":"MENTION_ONLY","pages":[10,10]},"NHI2022":{"status":"MENTION_ONLY","pages":[76,76,79,81]}}'::jsonb,15,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('e99fb7ee-2f77-5cf6-b978-187d7c857a31','FA16','Dị ứng nặng và phản vệ','OTHER','NHI nhắc phản vệ trong côn trùng đốt. Chọn bài người lớn PNT và đối chiếu NHS, không kê liều.','["Dị ứng nặng và phản vệ"]'::jsonb,'NHI nhắc phản vệ trong côn trùng đốt. Chọn bài người lớn PNT và đối chiếu NHS, không kê liều.','Dùng chung gọi cấp cứu, tư thế và hỗ trợ bút đã kê; không suy liều theo tuổi.','{"PNT2024":{"status":"DIRECT","pages":[24,24]},"NHI2022":{"status":"PARTIAL","pages":[93,94]}}'::jsonb,16,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('8f234c49-a546-5259-b864-482f9dd05ae0','FA17','Nghi ngộ độc','OTHER','Loại gây nôn, than hoạt, thuốc/liều ở NHI 77,79,80. Dùng NHS cho điều tránh an toàn.','["Nghi ngộ độc"]'::jsonb,'Loại gây nôn, than hoạt, thuốc/liều ở NHI 77,79,80. Dùng NHS cho điều tránh an toàn.','Dùng chung ngừng phơi nhiễm và gọi y tế; không tự gây nôn hay dùng thuốc. CPR theo độ tuổi.','{"PNT2024":{"status":"NOT_FOUND","pages":[]},"NHI2022":{"status":"DIRECT","pages":[75,81]}}'::jsonb,17,true) ON CONFLICT DO NOTHING;
INSERT INTO categories(id,code,name,group_code,description,keywords_json,coverage_note,audience_policy,pdf_evidence_json,sort_order,is_active) VALUES ('5489c849-0a1e-5b07-bec6-6720401a4098','FA18','Động vật cắn và côn trùng đốt','OTHER','Tách chó cắn, rắn cắn, ong đốt. Không bắt người dùng định loài rắn để tự chọn băng ép. Không suy thủ thuật kiến ba khoang thành bài ong.','["Động vật cắn và côn trùng đốt"]'::jsonb,'Tách chó cắn, rắn cắn, ong đốt. Không bắt người dùng định loài rắn để tự chọn băng ép. Không suy thủ thuật kiến ba khoang thành bài ong.','Dùng chung cho hai nhóm tuổi; tách chó cắn/rắn cắn/ong đốt vì cách xử trí khác nhau.','{"PNT2024":{"status":"DIRECT","pages":[25,30]},"NHI2022":{"status":"DIRECT","pages":[92,97]}}'::jsonb,18,true) ON CONFLICT DO NOTHING;
